import { Body, Controller, Delete, Get, Param, ParseIntPipe, Patch, Post, UseGuards } from '@nestjs/common';
import { CategoriasService } from './categorias.service';
import { AdminGuard } from '../auth/admin.guard';

@Controller()
export class CategoriasController {
  constructor(private service: CategoriasService) {}

  /** Público — listagem de categorias globais para home e cadastro de produtos */
  @Get('categorias/globais')
  listarGlobais() {
    return this.service.listarGlobais();
  }

  /** Público — tipos de estabelecimento (restaurante, farmácia, mat. construção...) pro cadastro */
  @Get('establishment-types')
  listarTiposEstabelecimento() {
    return this.service.listarTiposEstabelecimento();
  }

  /** Admin — CRUD de tipos de estabelecimento */
  @Post('establishment-types')
  @UseGuards(AdminGuard)
  criarTipoEstabelecimento(@Body() body: { name: string; icon_name?: string }) {
    return this.service.criarTipoEstabelecimento(body);
  }

  @Patch('establishment-types/:id')
  @UseGuards(AdminGuard)
  atualizarTipoEstabelecimento(
    @Param('id', ParseIntPipe) id: number,
